Bindings.Binding:
if not LFGParentFrame and GroupFinderVanillaStyle_LoadUI then
    GroupFinderVanillaStyle_LoadUI();
end
if LFGVanilla_ToggleFrame then
    LFGVanilla_ToggleFrame();
elseif ToggleGroupFinderFrame then
    ToggleGroupFinderFrame();
elseif ToggleLFGParentFrame then
    ToggleLFGParentFrame();
elseif ToggleLFDParentFrame then
    ToggleLFDParentFrame();
elseif PVEFrame_ToggleFrame then
    PVEFrame_ToggleFrame();
end
